function meu:define_ui()
	local ref = self.ref
	local ui = self.ui
    local ix,iy = 1,1
    local SY,DY = 1,.2

    self:add_rendering()    --todo why we get remdering from layer_c ???
	self:add_camera()
end

function meu:draw()
    self:draw_layers_begin()
        --  self:print( aaa.time.t )
        --self:draw_layer( 1 )
        self:draw_1( self:get_alpha(), 10, false )       -- choose the drawing function here
        self:draw_2( self:get_alpha(), 10, false )       -- choose the drawing function here
        -- self:draw_7( self:get_alpha(), 10, false )       -- choose the drawing function here
        self:draw_10( self:get_alpha(), 10, false )       -- choose the drawing function here
        self:draw_8( self:get_alpha(), 10, false )       -- choose the drawing function here
        self:draw_9( self:get_alpha(), 10, false )       -- choose the drawing function here
    self:draw_layers_end()

end

-- documentation is in
